const uint8_t *data = (const uint8_t *)buffer;
for (lfs_off_t i = 0; i < size; i += diff) {
    uint8_t dat[8];
    diff = std::min(size - (lfs_size_t)i, (lfs_size_t)sizeof(dat));
    int err = lfs_bd_read(lfs, pcache, rcache, hint - (lfs_size_t)i, block, off + i, dat, diff);
    if (err) {
        return err;
    }
    int res = memcmp(data + i, dat, diff);
    if (res != 0) {
        return (res < 0) ? LFS_CMP_LT : LFS_CMP_GT;
    }
}
return LFS_CMP_EQ;

